(function () {
  "use strict";
  const studio = window.DataHubStudio;
  if (!studio) return;
  const $ = selector => document.querySelector(selector);
  const $$ = selector => Array.from(document.querySelectorAll(selector));
  const esc = studio.escapeHtml;
  let marketFilter = "all", activeMeetingId = null, recognition = null;
  const connectors = [
    { id: "postgres", name: "PostgreSQL", category: "data", detail: "Read approved views through the secure gateway kit.", guide: "Create a read-only account, expose approved views through HTTPS, restrict CORS, and connect the JSON endpoint." },
    { id: "sqlserver", name: "SQL Server", category: "data", detail: "Connect operational or reporting databases safely.", guide: "Use a read-only login and a protected API using Microsoft Entra or your organization’s identity layer." },
    { id: "airtable", name: "Airtable", category: "business", detail: "Bring a shared view or gateway response into Studio.", guide: "For non-sensitive data use a read-only shared view. For private bases, keep the token behind a server gateway." },
