function sensitive(ds){const out=[],patterns=[[/name|full.?name|first.?name|last.?name/i,"Personal name"],[/email/i,"Email address"],[/phone|mobile|telephone/i,"Phone number"],[/ssn|social.?security/i,"Social Security number"],[/address|street|zip|postal/i,"Address or location"],[/dob|birth|birthday/i,"Date of birth"],[/account|card|routing|iban/i,"Financial identifier"],[/patient|medical|diagnosis|health|drug/i,"Health information"],[/employee.?id|student.?id|customer.?id|member.?id/i,"Individual identifier"]];for(const c of ds?.columns||[]){const match=patterns.find(([r])=>r.test(c));let kind=match?.[1];const vals=ds.rows.slice(0,200).map(r=>String(r[c]??""));if(!kind&&vals.some(v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)))kind="Email address";if(!kind&&vals.some(v=>/^\+?[\d ()-]{10,}$/.test(v)))kind="Phone number";if(kind)out.push({column:c,kind,count:vals.filter(Boolean).length})}return out}
async function load(){try{projects=await allProjects()}catch{projects=[studio.state.project]}renderCatalog()}
function renderCatalog(){const q=$("#catalog-search").value.trim().toLowerCase(),sets=projects.flatMap(p=>(p.datasets||[]).map(d=>({p,d,risks:sensitive(d).length}))).filter(x=>!q||(`${x.p.name} ${x.d.name} ${x.d.columns?.join(" ")}`).toLowerCase().includes(q));const rows=sets.reduce((n,x)=>n+(x.d.rows?.length||0),0);$("#portfolio-summary").innerHTML=[[projects.length,"Projects"],[sets.length,"Datasets"],[rows.toLocaleString(),"Cataloged rows"],[sets.reduce((n,x)=>n+x.risks,0),"Sensitive fields"]].map(x=>'<div class="portfolio-stat"><strong>'+x[0]+'</strong><span>'+x[1]+'</span></div>').join("");$("#catalog-table").innerHTML='<div class="catalog-row header"><span>Dataset</span><span>Project</span><span>Rows</span><span>Fields</span><span>Privacy</span></div>'+sets.map(x=>'<div class="catalog-row"><button data-open-project="'+x.p.id+'"><strong>'+esc(x.d.name)+'</strong><small>'+esc(x.d.source||"local")+'</small></button><span>'+esc(x.p.name)+'</span><span>'+Number(x.d.rows?.length||0).toLocaleString()+'</span><span>'+Number(x.d.columns?.length||0)+'</span><span class="badge '+(x.risks?"warn":"good")+'">'+(x.risks?x.risks+" flagged":"Clear")+'</span></div>').join("");$$('[data-open-project]').forEach(b=>b.onclick=()=>{localStorage.setItem("datahub_studio_active",b.dataset.openProject);location.reload()})}
function searchDialog(){studio.dialog('<span class="eyebrow">Portfolio search</span><h2>Search every project</h2><input id="portfolio-search-input" class="sn-input" placeholder="Dataset, metric, report, task, decision…" style="width:100%;margin-top:12px"><div id="portfolio-search-results" class="portfolio-search-results"></div>');$("#portfolio-search-input").oninput=e=>{const q=e.target.value.trim().toLowerCase(),hits=[];if(q.length>1)for(const p of projects){const add=(type,label)=>hits.push({project:p,type,label});if(p.name.toLowerCase().includes(q))add("Project",p.name);for(const d of p.datasets||[])if((d.name+" "+(d.columns||[]).join(" ")).toLowerCase().includes(q))add("Dataset",d.name);for(const [type,list] of [["Task",p.tasks],["Decision",p.decisions],["Metric",p.metrics],["Report",p.stories]])for(const x of list||[])if(JSON.stringify(x).toLowerCase().includes(q))add(type,x.title||x.name||x.text||x.label||type)}$("#portfolio-search-results").innerHTML=hits.slice(0,40).map((h,i)=>'<button class="portfolio-search-result" data-search-hit="'+i+'"><span>⌕</span><span><b>'+esc(h.label)+'</b><small>'+esc(h.project.name)+'</small></span><em>'+h.type+'</em></button>').join("")||'<p class="muted">'+(q.length>1?"No matches found.":"Type at least two characters.")+'</p>';$$('[data-search-hit]').forEach(b=>b.onclick=()=>{const h=hits[+b.dataset.searchHit];localStorage.setItem("datahub_studio_active",h.project.id);location.reload()})};setTimeout(()=>$("#portfolio-search-input").focus(),60)}
function scan(){const d=studio.activeDataset();if(!d)return studio.toast("Select a dataset first.");findings=sensitive(d);$("#portfolio-privacy-findings").innerHTML=findings.length?findings.map(f=>'<div class="privacy-finding"><span><strong>'+esc(f.column)+'</strong><span>'+esc(f.kind)+' · '+f.count+' populated values</span></span><b class="privacy-level">Review</b></div>').join(""):'<p class="muted">No common sensitive fields were detected. Review unusual identifiers manually.</p>';studio.toast(findings.length+" potentially sensitive field"+(findings.length===1?"":"s")+" found.")}
function hash(v){let h=2166136261;for(const c of String(v)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return"id_"+(h>>>0).toString(16)}
function redact(){const d=studio.activeDataset();if(!d)return studio.toast("Select a dataset first.");if(!findings.length)scan();if(!findings.length)return;const mode=$("#redaction-mode").value,flag=new Set(findings.map(f=>f.column)),columns=mode==="remove"?d.columns.filter(c=>!flag.has(c)):[...d.columns],rows=d.rows.map(r=>Object.fromEntries(columns.map(c=>[c,flag.has(c)?(mode==="hash"?hash(r[c]):String(r[c]??"").replace(/.(?=.{4})/g,"•")):r[c]])));const copy={id:studio.uid("data"),name:d.name.replace(/(\.[^.]+)?$/," • protected$1"),columns,rows,originalRowCount:rows.length,source:"redacted",addedAt:Date.now()};studio.state.project.datasets.push(copy);studio.state.project.activeDatasetId=copy.id;studio.addActivity("Protected dataset created");studio.renderAll();studio.saveProject(true);studio.toast("Protected dataset created.")}
function saveTemplate(){const name=$("#template-name").value.trim();if(!name)return studio.toast("Name the template first.");const p=studio.state.project,t=templates();t.unshift({id:studio.uid("template"),name,description:$("#template-description").value.trim(),at:new Date().toLocaleString(),structure:{goal:p.goal,steps:p.steps,rules:p.rules,dashboardWidgets:p.dashboardWidgets,calculatedFields:p.calculatedFields,reportDesigns:p.reportDesigns,metricRegistry:p.metricRegistry}});saveTemplates(t.slice(0,30));$("#template-name").value="";$("#template-description").value="";renderTemplates();studio.toast("Project template saved.")}
function renderTemplates(){const t=templates();$("#template-library").innerHTML=t.length?t.map(x=>'<div class="template-card"><span><strong>'+esc(x.name)+'</strong><small>'+esc(x.description||x.at)+'</small></span><div class="template-card-actions"><button class="icon-button" data-use-template="'+x.id+'">Use</button><button class="icon-button" data-delete-template="'+x.id+'">×</button></div></div>').join(""):'<p class="muted">No templates saved yet.</p>';$$('[data-use-template]').forEach(b=>b.onclick=()=>{const x=t.find(v=>v.id===b.dataset.useTemplate);Object.assign(studio.state.project,JSON.parse(JSON.stringify(x.structure)));studio.addActivity("Template applied: "+x.name);studio.renderAll();studio.saveProject(true);studio.toast("Template applied to this project.")});$$('[data-delete-template]').forEach(b=>b.onclick=()=>{saveTemplates(t.filter(x=>x.id!==b.dataset.deleteTemplate));renderTemplates()})}
async function reliability(){const checks=[];const add=(name,ok,detail)=>checks.push({name,ok,detail});add("Project storage",!!window.indexedDB,"IndexedDB is available");add("Offline worker","serviceWorker" in navigator,"Browser supports offline caching");add("Encryption",!!window.crypto?.subtle,"Secure sharing APIs available");add("Live collaboration","BroadcastChannel" in window,"Cross-tab collaboration available");const p=studio.state.project;add("Project structure",!!p?.id&&Array.isArray(p.datasets),"Current project schema is valid");add("Dataset integrity",p.datasets.every(d=>Array.isArray(d.columns)&&Array.isArray(d.rows)),p.datasets.length+" datasets checked");const urls=["../../index.html","../code-helper/index.html","../data-analyzer/index.html","../dashboard-builder/index.html"];for(const url of urls){try{const r=await fetch(url,{method:"HEAD",cache:"no-store"});add("Route: "+url.split("/").slice(-2,-1)[0],r.ok,"HTTP "+r.status)}catch{add("Route: "+url,false,"Could not reach route")}}const passed=checks.filter(x=>x.ok).length,score=Math.round(passed/checks.length*100);$("#reliability-score").innerHTML='<strong>'+score+'</strong><span>'+passed+' of '+checks.length+' platform checks passed</span>';$("#reliability-checks").innerHTML=checks.map(x=>'<div class="reliability-check '+(x.ok?"":"fail")+'"><span><strong>'+esc(x.name)+'</strong><span>'+esc(x.detail)+'</span></span><i></i></div>').join("")}
$$('[data-portfolio-tab]').forEach(b=>b.onclick=()=>{$$('[data-portfolio-tab]').forEach(x=>x.classList.toggle("active",x===b));$$('.portfolio-panel').forEach(x=>x.classList.toggle("active",x.id==="portfolio-"+b.dataset.portfolioTab))});$("#portfolio-search-btn").onclick=searchDialog;$("#catalog-search").oninput=renderCatalog;$("#run-privacy-scan").onclick=scan;$("#portfolio-redact-dataset-btn").onclick=redact;$("#save-template-btn").onclick=saveTemplate;$("#run-reliability-btn").onclick=reliability;window.addEventListener("datahub:project-render",()=>{renderTemplates();if(findings.length)scan()});load();renderTemplates();
})();

