  function renderPins(){const items=project().pinnedInsights,panel=$("#pinned-insights-panel");panel.hidden=!items.length;$("#pinned-insights-count").textContent=items.length+" pinned";$("#pinned-insights").innerHTML=items.map(x=>'<article class="pinned-insight"><button data-unpin="'+x.id+'">×</button><small>'+esc(x.dataset)+'</small><strong>'+esc(x.title)+'</strong><span>'+esc(x.subtitle)+'</span></article>').join("");$$('[data-unpin]').forEach(b=>b.onclick=()=>{project().pinnedInsights=items.filter(x=>x.id!==b.dataset.unpin);studio.markDirty();renderPins()})}
