tools/studio/studio-shell.css:

body.studio-app { padding-bottom: 0 !important; --studio-top: 56px; }


.studio-app .studio-topbar {
  position: sticky; top: 0; z-index: var(--sn-z-nav);
  display: flex; flex-direction: row; flex-wrap: nowrap; align-items: center; gap: 10px;
  min-height: var(--studio-top); height: var(--studio-top); padding: 0 14px;
  border-bottom: 1px solid var(--sn-line); background: color-mix(in srgb, var(--sn-bg) 82%, transparent);
  backdrop-filter: blur(20px) saturate(1.3); -webkit-backdrop-filter: blur(20px) saturate(1.3); box-shadow: none;
}
.studio-app .studio-topbar::after { display: none; }
.studio-brand .sn-brand-name { font-size: 14px; }
.studio-crumb-sep { color: var(--sn-text-4); }
.studio-project-title { display: flex; align-items: center; gap: 10px; min-width: 0; }
.studio-project-title strong { overflow: hidden; color: var(--sn-text); font: 600 14px/1.2 var(--sn-font-sans); white-space: nowrap; text-overflow: ellipsis; max-width: 32vw; }
.studio-mode-pill { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border: 1px solid color-mix(in srgb, var(--sn-success) 32%, transparent); border-radius: var(--sn-radius-pill); background: var(--sn-success-soft); color: var(--sn-success); font: 600 11.5px/1 var(--sn-font-sans); cursor: pointer; white-space: nowrap; }
.studio-mode-pill .sn-dot { width: 6px; height: 6px; }
.studio-mode-pill:hover { border-color: var(--sn-success); }
.studio-app .project-controls { margin-left: auto; display: flex; align-items: center; gap: 6px; width: auto; padding: 0; border: 0; background: none; box-shadow: none; overflow: visible; }
.studio-app .save-status { color: var(--sn-text-4); font: 500 11.5px/1 var(--sn-font-mono); white-space: nowrap; }
.studio-app .save-status.saving { color: var(--sn-warning); }
.studio-app .save-status.failed { color: var(--sn-danger); font-weight: 700; }

@media (max-width: 720px) { .studio-app .save-status.failed { display: inline !important; } }
.studio-app .chat-launch { position: relative; }
.studio-app #chat-unread { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 99px; background: var(--sn-accent); color: #fff; font-size: 10px; }
.studio-app #chat-unread[hidden] { display: none; }
.studio-sidebar-toggle { display: none; }
.studio-more { position: relative; }
.studio-more summary { list-style: none; }
.studio-more summary::-webkit-details-marker { display: none; }
.studio-more-menu { position: absolute; right: 0; top: calc(100% + 8px); z-index: var(--sn-z-drawer); display: grid; width: 240px; padding: 6px; border: 1px solid var(--sn-line-strong); border-radius: var(--sn-radius-md); background: var(--sn-surface); box-shadow: var(--sn-shadow-lg); animation: snRise var(--sn-dur-2) var(--sn-ease); }
.studio-more-menu button { display: flex; align-items: center; gap: 10px; min-height: 36px; padding: 0 10px; border: 0; border-radius: 8px; background: transparent; color: var(--sn-text-2); font: 500 13px/1 var(--sn-font-sans); text-align: left; cursor: pointer; }
.studio-more-menu button:hover { background: var(--sn-surface-2); color: var(--sn-text); }
.studio-more-menu button span { width: 18px; color: var(--sn-text-4); text-align: center; }
.studio-more-menu b { margin-left: auto; color: var(--sn-text-4); font: 500 11px/1 var(--sn-font-mono); }
.studio-app #focus-mode-btn.focus-exit { color: var(--sn-accent-strong); }


.studio-app .studio-shell { display: grid; grid-template-columns: 248px minmax(0, 1fr) 340px; min-height: calc(100vh - var(--studio-top)); }
body.studio-app.ctx-collapsed .studio-shell { grid-template-columns: 248px minmax(0, 1fr); }
body.studio-app.ctx-collapsed .studio-context { display: none; }


.studio-app .studio-sidebar {
  position: sticky; top: var(--studio-top); z-index: 20; height: calc(100vh - var(--studio-top));
  display: flex; flex-direction: column; gap: 18px; padding: 16px 12px; overflow-y: auto;
